const SUPABASE_KEY="sb_publishable_0dVqqdCdDrFgqRfh7E1DvQ_uhJvj1Bh";
const sb=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);
const $=s=>document.querySelector(s), money=n=>`$${Number(n||0).toFixed(2)}`, today=()=>new Date().toISOString().slice(0,10);
const esc=(s="")=>String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
let db={clients:[],memberships:[],products:[],sales:[],expenses:[],classes:[],team:[],bookings:[],class_levels:[],package_orders:[],notification_settings:[],notification_queue:[],studio_settings:[],announcements:[],promo_codes:[],custom_sections:[],custom_entries:[],audit_log:[],instructor_availability:[]};
let session=null,profile=null,page="dashboard",cart=[],scheduleWeekOffset=0,studioTab="Pilates";
const isOwner=()=>profile?.role==="owner",isInstructor=()=>profile?.role==="instructor",isClient=()=>profile?.role==="client",isStaff=()=>isOwner()||isInstructor();
const PHONE_COUNTRIES=[['Lebanon','+961'],['France','+33'],['United Arab Emirates','+971'],['Kuwait','+965'],['Saudi Arabia','+966'],['Qatar','+974'],['Bahrain','+973'],['Jordan','+962'],['Egypt','+20'],['Cyprus','+357'],['Greece','+30'],['Italy','+39'],['Spain','+34'],['Portugal','+351'],['Germany','+49'],['United Kingdom','+44'],['Ireland','+353'],['Switzerland','+41'],['Belgium','+32'],['Netherlands','+31'],['Sweden','+46'],['Norway','+47'],['Denmark','+45'],['Austria','+43'],['United States / Canada','+1'],['Australia','+61'],['New Zealand','+64'],['Turkey','+90'],['Armenia','+374'],['Georgia','+995'],['Iraq','+964'],['Oman','+968'],['Morocco','+212'],['Tunisia','+216'],['Algeria','+213'],['South Africa','+27'],['India','+91'],['Philippines','+63'],['Other','']];
const countryOptions=()=>PHONE_COUNTRIES.map(([n,c])=>`<option value="${c}" ${c==='+961'?'selected':''}>${n}${c?' ('+c+')':''}</option>`).join('');


function authScreen(msg=""){$("#app").innerHTML=`<div class="auth-shell"><div class="auth-card"><div class="auth-brand">CORE THEORY<small>PILATES · MEGACORE</small></div><h2>Sign in</h2><form id="loginForm"><label>Email</label><input id="loginEmail" type="email" required><label>Password</label><input id="loginPassword" type="password" required><button class="btn primary full" type="submit">Sign in</button><div class="auth-error" id="authError">${esc(msg)}</div></form><div class="auth-links"><button class="link-btn" onclick="forgotPassword()">Forgot password?</button><button class="link-btn" onclick="signupScreen()">New client? Create account</button></div></div></div>`;$("#loginForm").onsubmit=login}
async function login(e){e.preventDefault();$("#authError").textContent="Signing in…";const {data,error}=await sb.auth.signInWithPassword({email:$("#loginEmail").value.trim(),password:$("#loginPassword").value});if(error)return $("#authError").textContent=error.message;session=data.session;await loadAll()}
function signupScreen(msg=""){$("#app").innerHTML=`<div class="auth-shell"><div class="auth-card"><div class="auth-brand">CORE THEORY<small>CLIENT ACCOUNT</small></div><h2>Create account</h2><form id="signupForm"><label>Full name</label><input id="suName" required><label>Email</label><input id="suEmail" type="email" required><label>Country / calling code</label><select id="suCountry" required>${countryOptions()}</select><label>Phone number</label><input id="suPhone" type="tel" placeholder="e.g. 70123456" required><small class="muted">Choose your country first. Core Theory saves the full international number.</small><label>Password</label><input id="suPass" type="password" minlength="8" required><button class="btn primary full" type="submit">Create account</button><div class="auth-error" id="authError">${esc(msg)}</div></form><button class="link-btn" onclick="authScreen()">← Back to sign in</button></div></div>`;$("#signupForm").onsubmit=signup}
async function signup(e){e.preventDefault();const code=$("#suCountry").value.trim(),raw=$("#suPhone").value.trim().replace(/^0+/,'').replace(/\s+/g,'');if(!code)return $("#authError").textContent="Please choose a country with a calling code.";if(!raw)return $("#authError").textContent="Phone number is required.";const phone=code+raw;const {error}=await sb.auth.signUp({email:$("#suEmail").value.trim(),password:$("#suPass").value,options:{emailRedirectTo:location.origin,data:{full_name:$("#suName").value.trim(),phone,phone_country_code:code}}});if(error)return $("#authError").textContent=error.message;authScreen("Account created. Check your email to confirm, then sign in.")}
async function forgotPassword(){const email=prompt("Enter your Core Theory email:");if(!email)return;const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin});alert(error?error.message:"Password reset email sent.")}
function setPasswordScreen(){$("#app").innerHTML=`<div class="auth-shell"><div class="auth-card"><div class="auth-brand">CORE THEORY<small>SECURE ACCOUNT</small></div><h2>Create your password</h2><p class="muted">Choose the password you'll use to sign in.</p><form id="pwForm"><label>New password</label><input id="pw1" type="password" minlength="8" required><label>Confirm password</label><input id="pw2" type="password" minlength="8" required><button class="btn primary full" type="submit">Save password</button><div class="auth-error" id="authError"></div></form></div></div>`;$("#pwForm").onsubmit=savePassword}
async function savePassword(e){e.preventDefault();if($("#pw1").value!==$("#pw2").value)return $("#authError").textContent="Passwords do not match.";const {error}=await sb.auth.updateUser({password:$("#pw1").value});if(error)return $("#authError").textContent=error.message;history.replaceState({},document.title,location.pathname);await loadAll()}
async function logout(){await sb.auth.signOut();session=null;profile=null;authScreen()}

async function loadAll(){if(!session)return authScreen();$("#app").innerHTML='<div class="loading">Loading Core Theory…</div>';let pr=await sb.from("profiles").select("*").eq("id",session.user.id).maybeSingle();if(pr.error)return authScreen("Profile error: "+pr.error.message);profile=pr.data;if(!profile)return authScreen("This account does not have a Core Theory profile yet.");if(isClient())await sb.rpc("ensure_client_record");const tables=isOwner()?['clients','memberships','products','sales','expenses','classes','team','bookings','class_levels','package_orders','notification_settings','notification_queue','studio_settings','announcements','promo_codes','custom_sections','custom_entries','audit_log','instructor_availability']:isInstructor()?['classes','bookings','class_levels']:['clients','memberships','classes','bookings','class_levels','package_orders'];db={clients:[],memberships:[],products:[],sales:[],expenses:[],classes:[],team:[],bookings:[],class_levels:[],package_orders:[],notification_settings:[],notification_queue:[],studio_settings:[],announcements:[],promo_codes:[],custom_sections:[],custom_entries:[],audit_log:[],instructor_availability:[],roster:[]};const rs=await Promise.all(tables.map(t=>sb.from(t).select("*")));const bad=rs.find(x=>x.error);if(bad)return authScreen("Database error: "+bad.error.message);tables.forEach((t,i)=>db[t]=rs[i].data||[]);if(isInstructor()){const rr=await sb.rpc('my_instructor_roster');if(rr.error)return authScreen('Schedule access error: '+rr.error.message);db.roster=rr.data||[];}if(isInstructor()&&!['schedule','account'].includes(page))page='schedule';if(isClient()&&!['book','mybookings','packages','clientaccount'].includes(page))page='book';render()}
function nav(){const pages=isOwner()?['dashboard','clients','schedule','pos','memberships','inventory','expenses','finance','team','operations','settings']:isInstructor()?['schedule','account']:['book','mybookings','packages','clientaccount'];const labels={dashboard:'⌂ Dashboard',clients:'◎ Clients',schedule:'□ Schedule',pos:'$ POS / Sales',memberships:'◇ Memberships',inventory:'▣ Inventory',expenses:'− Expenses',finance:'↗ Finance',team:'◌ Team',operations:'✦ Operations',settings:'⚙ Settings',payment:'$ Record Payment',account:'⚙ Account',book:'□ Book a Class',mybookings:'✓ My Bookings',packages:'◇ Packages',clientaccount:'◎ My Account'};return pages.map(x=>`<button data-page="${x}" class="${page===x?'active':''}">${labels[x]}</button>`).join('')+(isOwner()?db.custom_sections.filter(x=>x.visible_owner!==false).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)).map(x=>`<button data-custom="${x.id}" class="${page==='custom:'+x.id?'active':''}">${esc(x.icon||'•')} ${esc(x.name)}</button>`).join(''):'')}
function layout(content,title,subtitle=''){const role=isOwner()?'Owner':isInstructor()?'Instructor':'Client';$("#app").innerHTML=`<div class="app"><aside class="sidebar"><div class="brand">CORE THEORY<small>${role} Portal</small></div><div class="nav">${nav()}</div><div class="role-chip">${esc(profile?.full_name||profile?.email||'')}<small>${role}</small></div><button class="btn logout" onclick="logout()">Log out</button></aside><main class="main"><div class="topbar"><div><h1>${title}</h1><p>${subtitle}</p><div class="sync-note">☁ Cloud connected</div></div><button class="btn" onclick="loadAll()">Refresh</button></div>${content}</main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});document.querySelectorAll('[data-custom]').forEach(b=>b.onclick=()=>{page='custom:'+b.dataset.custom;render()})}
function render(){if(page.startsWith('custom:'))return customSectionPage(page.split(':')[1]);const f={dashboard,clients,schedule,pos,memberships,inventory,expenses,finance,team,operations,settings,payment,account,book,mybookings,packages,clientaccount}[page];(f||schedule)()}

const bookingCount=id=>db.bookings.filter(b=>String(b.class_id)===String(id)&&!['cancelled'].includes(b.status)).length;
const activeBookings=id=>db.bookings.filter(b=>String(b.class_id)===String(id)&&b.status!=='cancelled');
function dashboard(){const rev=db.sales.reduce((a,s)=>a+Number(s.total||0),0),exp=db.expenses.reduce((a,e)=>a+Number(e.amount||0),0);layout(`<div class="grid kpis"><div class="card kpi"><div class="label">Revenue</div><div class="value">${money(rev)}</div></div><div class="card kpi"><div class="label">Expenses</div><div class="value">${money(exp)}</div></div><div class="card kpi"><div class="label">Estimated profit</div><div class="value">${money(rev-exp)}</div></div><div class="card kpi"><div class="label">Clients</div><div class="value">${db.clients.length}</div></div></div><div class="spacer"></div><div class="card"><h3>Today's classes</h3>${db.classes.filter(c=>c.class_date===today()).map(classCard).join('')||'<div class="empty">No classes today.</div>'}</div>`,`Dashboard`,`Your studio at a glance`)}
function clients(){layout(`<div class="card">${isOwner()?'<div class="toolbar"><button class="btn primary" onclick="clientModal()">+ Add client</button></div>':''}${db.clients.length?`<table><thead><tr><th>Client</th><th>Phone</th><th>Package</th><th>Sessions</th><th>Expiry</th>${isOwner()?'<th></th>':''}</tr></thead><tbody>${db.clients.map(c=>`<tr><td><b>${esc(c.name)}</b><div class="muted">${esc(c.email||'')}</div></td><td>${esc(c.phone||'')}</td><td>${esc(c.package||'—')}</td><td>${c.sessions??0}</td><td>${esc(c.expiry||'—')}</td>${isOwner()?`<td><button class="btn small" onclick="clientHistory('${c.id}')">History</button> <button class="btn small" onclick="sellMembership('${c.id}')">Add package</button></td>`:''}</tr>`).join('')}</tbody></table>`:'<div class="empty">No clients yet.</div>'}</div>`,`Clients`,isOwner()?'Packages, attendance and payment history':'Client details and package balances')}
function clientHistory(id){const c=db.clients.find(x=>String(x.id)===String(id)),bs=db.bookings.filter(b=>String(b.client_id)===String(id));modal(`${esc(c?.name||'Client')} history`,`<p><b>Package:</b> ${esc(c?.package||'—')} · <b>Sessions:</b> ${c?.sessions??0} · <b>Expiry:</b> ${esc(c?.expiry||'—')}</p><h3>Attendance / bookings</h3>${bs.map(b=>{const cl=db.classes.find(x=>String(x.id)===String(b.class_id));return `<div class="cart-row"><span>${esc(cl?.class_date||'')} · ${esc(cl?.class_type||'Class')}</span><span class="badge">${esc(b.status)}</span></div>`}).join('')||'<div class="empty">No booking history.</div>'}`)}

function mondayOfWeek(offset=0){const d=new Date(),day=(d.getDay()+6)%7;d.setHours(12,0,0,0);d.setDate(d.getDate()-day+offset*7);return d}const dateISO=d=>d.toISOString().slice(0,10);function formatTime(t){const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
function levelColor(level){return db.class_levels.find(x=>x.name===level)?.color||'#eee8df'}
function schedule(){const mon=mondayOfWeek(scheduleWeekOffset),days=[];for(let i=0;i<6;i++){const d=new Date(mon);d.setDate(mon.getDate()+i);days.push(d)}layout(`<div class="schedule-tabs"><button class="tab ${studioTab==='Pilates'?'active':''}" onclick="studioTab='Pilates';schedule()">PILATES</button><button class="tab ${studioTab==='Megacore'?'active':''}" onclick="studioTab='Megacore';schedule()">MEGACORE</button></div><div class="schedule-tools"><div class="toolbar">${isOwner()?'<button class="btn primary" onclick="classModal()">+ Add class</button>':''}<button class="btn" onclick="scheduleWeekOffset--;schedule()">← Previous</button><button class="btn" onclick="scheduleWeekOffset=0;schedule()">This week</button><button class="btn" onclick="scheduleWeekOffset++;schedule()">Next →</button></div></div>${scheduleTable(days,studioTab)}`,`Schedule`,`${studioTab} weekly timetable — same times stay on the same row`)}
function scheduleTable(days,type){const dates=new Set(days.map(dateISO)),cs=db.classes.filter(c=>dates.has(c.class_date)&&(c.studio_type||'Pilates')===type),times=[...new Set(cs.map(c=>(c.class_time||'').slice(0,5)).filter(Boolean))].sort();if(!times.length)for(let h=7;h<=20;h++)times.push(String(h).padStart(2,'0')+':00');return `<div class="card schedule-wrap"><table class="weekly-schedule"><thead><tr><th class="time-col">Time</th>${days.map(d=>`<th>${d.toLocaleDateString(undefined,{weekday:'long'})}<small>${d.toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small></th>`).join('')}</tr></thead><tbody>${times.map(t=>`<tr><th class="time-col">${formatTime(t)}</th>${days.map(d=>`<td class="schedule-cell">${cs.filter(c=>c.class_date===dateISO(d)&&(c.class_time||'').slice(0,5)===t).map(classCard).join('')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function classCard(c){const n=bookingCount(c.id);return `<div class="class-card" style="--level:${levelColor(c.level)}" onclick="openClass('${c.id}')"><b>${esc(c.class_type||'Class')}</b><span>${esc(c.level||'Open Level')} · ${esc(c.instructor||'No instructor')}</span><small>${formatTime((c.class_time||'00:00').slice(0,5))} · ${n}/${c.capacity||0} booked</small></div>`}
function openClass(id){const c=db.classes.find(x=>String(x.id)===String(id));if(!c)return;const bs=activeBookings(id);const rows=bs.map(b=>{const roster=db.roster?.find(r=>String(r.booking_id)===String(b.id));const cl=isOwner()?db.clients.find(x=>String(x.id)===String(b.client_id)):null;const clientName=cl?.name||roster?.client_name||'Client';return `<div class="booking-person"><span><b>${esc(clientName)}</b><small>${esc(b.status)}</small></span>${isStaff()?`<span>${b.status==='booked'?`<button class="btn small" onclick="checkIn('${b.id}')">Check in</button>`:''}<button class="btn small" onclick="setBookingStatus('${b.id}','no_show')">No-show</button></span>`:''}</div>`}).join('');modal(`${esc(c.class_type)} · ${formatTime((c.class_time||'00:00').slice(0,5))}`,`<p><span class="badge" style="background:${levelColor(c.level)}">${esc(c.level||'Open Level')}</span> ${esc(c.studio_type||'Pilates')} · ${esc(c.instructor||'')}</p><h3>Bookings ${bs.length}/${c.capacity||0}</h3>${rows||'<div class="empty">No bookings yet.</div>'}${isOwner()?`<button class="btn primary" onclick="addBookingModal('${c.id}')">+ Add client</button> <button class="btn" onclick="$('#modal').remove();editClassModal('${c.id}')">Edit class</button>`:''}`)}
function addBookingModal(classId){const booked=new Set(activeBookings(classId).map(b=>String(b.client_id)));modal('Add client to class',`<div class="form"><div class="full"><label>Client</label><select id="bkclient">${db.clients.filter(c=>!booked.has(String(c.id))).map(c=>`<option value="${c.id}">${esc(c.name)} · ${c.sessions??0} sessions</option>`).join('')}</select></div><div class="full"><button class="btn primary" onclick="staffBook('${classId}')">Add booking</button></div></div>`)}
async function staffBook(classId){const clientId=$("#bkclient").value;if(!clientId)return;const {error}=await sb.from('bookings').insert({class_id:String(classId),client_id:String(clientId),created_by:session.user.id});if(error)return alert(error.message);$("#modal").remove();await loadAll();openClass(classId)}
async function checkIn(bookingId){const {error}=await sb.rpc('check_in_booking',{p_booking_id:bookingId});if(error)return alert(error.message);await loadAll();alert('Checked in. Session deducted.')}
async function setBookingStatus(id,status){const {error}=await sb.from('bookings').update({status}).eq('id',id);if(error)return alert(error.message);$("#modal")?.remove();await loadAll()}

function classModal(){modal('Add class',classForm())}function classForm(c={}){return `<div class="form"><div><label>Date</label><input type="date" id="cldate" value="${c.class_date||today()}"></div><div><label>Time</label><input type="time" id="cltime" value="${(c.class_time||'').slice(0,5)}"></div><div><label>Studio</label><select id="clstudio"><option ${c.studio_type==='Pilates'?'selected':''}>Pilates</option><option ${c.studio_type==='Megacore'?'selected':''}>Megacore</option></select></div><div><label>Level</label><select id="cllevel">${db.class_levels.map(l=>`<option ${c.level===l.name?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div><label>Class name</label><input id="cltype" value="${esc(c.class_type||'')}" placeholder="Rise & Shine"></div><div><label>Instructor</label><select id="clinstructor">${db.team.filter(t=>t.role==='Instructor'&&t.auth_user_id).map(t=>`<option value="${t.auth_user_id}" data-name="${esc(t.name)}" ${String(c.instructor_user_id||'')===String(t.auth_user_id)?'selected':''}>${esc(t.name)}</option>`).join('')}<option value="" ${!c.instructor_user_id?'selected':''}>Unassigned</option></select></div><div><label>Capacity</label><input type="number" id="clcap" value="${c.capacity||10}"></div>${!c.id?'<div><label>Repeat weekly</label><select id="clrepeat"><option value="1">No</option><option value="4">4 weeks</option><option value="8">8 weeks</option><option value="12">12 weeks</option></select></div>':''}<div class="full"><button class="btn primary" onclick="${c.id?`saveClass('${c.id}')`:'addClass()'}">Save</button>${c.id?` <button class="btn danger" onclick="deleteClass('${c.id}')">Delete</button>`:''}</div></div>`}
async function addClass(){const repeats=+$("#clrepeat").value,base=new Date($("#cldate").value+'T12:00:00'),group=crypto.randomUUID(),rows=[];for(let i=0;i<repeats;i++){const d=new Date(base);d.setDate(base.getDate()+7*i);rows.push({class_date:dateISO(d),class_time:$("#cltime").value,class_type:$("#cltype").value,instructor:$("#clinstructor").selectedOptions[0]?.dataset.name||'',instructor_user_id:$("#clinstructor").value||null,capacity:+$("#clcap").value,studio_type:$("#clstudio").value,level:$("#cllevel").value,recurring_group:repeats>1?group:null})}const {error}=await sb.from('classes').insert(rows);if(error)return alert(error.message);$("#modal").remove();await loadAll()}
function editClassModal(id){const c=db.classes.find(x=>String(x.id)===String(id));modal('Edit class',classForm(c))}async function saveClass(id){const {error}=await sb.from('classes').update({class_date:$("#cldate").value,class_time:$("#cltime").value,class_type:$("#cltype").value,instructor:$("#clinstructor").selectedOptions[0]?.dataset.name||'',instructor_user_id:$("#clinstructor").value||null,capacity:+$("#clcap").value,studio_type:$("#clstudio").value,level:$("#cllevel").value}).eq('id',id);if(error)return alert(error.message);$("#modal").remove();await loadAll()}async function deleteClass(id){if(!confirm('Delete this class?'))return;const {error}=await sb.from('classes').delete().eq('id',id);if(error)return alert(error.message);$("#modal").remove();await loadAll()}

function book(){const days=[];for(let i=0;i<14;i++){const d=new Date();d.setDate(d.getDate()+i);days.push(d)}const cs=db.classes.filter(c=>days.map(dateISO).includes(c.class_date));layout(`<div class="schedule-tabs"><button class="tab ${studioTab==='Pilates'?'active':''}" onclick="studioTab='Pilates';book()">PILATES</button><button class="tab ${studioTab==='Megacore'?'active':''}" onclick="studioTab='Megacore';book()">MEGACORE</button></div><div class="client-class-grid">${cs.filter(c=>(c.studio_type||'Pilates')===studioTab).sort((a,b)=>(a.class_date+a.class_time).localeCompare(b.class_date+b.class_time)).map(c=>{const n=bookingCount(c.id),full=n>=Number(c.capacity||0);return `<div class="card client-class"><div class="date">${new Date(c.class_date+'T12:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</div><h3>${esc(c.class_type)}</h3><span class="badge" style="background:${levelColor(c.level)}">${esc(c.level||'Open Level')}</span><p>${formatTime((c.class_time||'00:00').slice(0,5))} · ${esc(c.instructor||'')}</p><p class="muted">${Math.max(0,Number(c.capacity||0)-n)} spots remaining</p><button class="btn primary" ${full?'disabled':''} onclick="clientBook('${c.id}')">${full?'Full':'Book'}</button></div>`}).join('')||'<div class="empty">No upcoming classes.</div>'}</div>`,`Book a Class`,`Choose Pilates or Megacore and reserve your spot`)}
function myClient(){return db.clients[0]}
function packageEligible(m,cl){const scope=m.studio_scope||'Both',type=cl.studio_type||'Pilates';return scope==='Both'||scope===type}
function clientBook(classId){const c=myClient(),cl=db.classes.find(x=>String(x.id)===String(classId));if(!c||!cl)return alert('Booking details are not ready. Refresh and try again.');if(db.bookings.some(b=>String(b.class_id)===String(classId)&&String(b.client_id)===String(c.id)&&b.status!=='cancelled'))return alert('You are already booked.');if(bookingCount(classId)>=Number(cl.capacity||0))return alert('This class is full.');const eligible=db.memberships.filter(m=>packageEligible(m,cl));const currentOk=(Number(c.sessions)===999||Number(c.sessions)>0)&&(!c.package_scope||c.package_scope==='Both'||c.package_scope===(cl.studio_type||'Pilates'));modal('Choose package',`<p><b>${esc(cl.class_type)}</b> · ${esc(cl.studio_type||'Pilates')} · ${esc(cl.class_date)}</p><label>How would you like to book?</label><select id="bookPackage">${currentOk?`<option value="current">Use my current package (${c.sessions===999?'Unlimited':c.sessions+' sessions left'})</option>`:''}${eligible.map(m=>`<option value="buy:${m.id}">Buy ${esc(m.name)} — ${money(m.price)} · Pay at Front Desk</option>`).join('')}</select><p class="muted">Packages selected here are marked Payment Pending until the front desk marks them paid.</p><button class="btn primary full" onclick="confirmClientBooking('${classId}')">Confirm booking</button>`)}
async function confirmClientBooking(classId){const c=myClient(),cl=db.classes.find(x=>String(x.id)===String(classId)),choice=$("#bookPackage")?.value;if(!choice)return alert('Please choose a package.');let orderId=null,membershipId=null,paymentStatus='paid';if(choice==='current'){if(Number(c.sessions)!==999&&Number(c.sessions)<=0)return alert('Your current package has no sessions remaining.')}else{membershipId=choice.split(':')[1];const m=db.memberships.find(x=>String(x.id)===String(membershipId));if(!m||!packageEligible(m,cl))return alert('That package cannot be used for this class.');const pending=db.package_orders.find(o=>o.status==='pending');if(pending)return alert('You already have a package waiting for payment at the front desk. Please settle it before starting another unpaid package.');const {data:o,error:oe}=await sb.from('package_orders').insert({client_id:String(c.id),membership_id:String(m.id),amount:m.price,status:'pending',payment_method:'front_desk',class_id:String(classId)}).select().single();if(oe)return alert(oe.message);orderId=o.id;paymentStatus='pending'}const {error}=await sb.from('bookings').insert({class_id:String(classId),client_id:String(c.id),created_by:session.user.id,membership_id:membershipId,package_order_id:orderId,payment_status:paymentStatus});if(error)return alert(error.message);$("#modal")?.remove();await loadAll();alert(paymentStatus==='pending'?'Booked! Your package payment is due at the front desk.':'Booked!')}
function mybookings(){const c=myClient(),bs=db.bookings.filter(b=>String(b.client_id)===String(c?.id)&&b.status!=='cancelled');layout(`<div class="card">${bs.map(b=>{const cl=db.classes.find(x=>String(x.id)===String(b.class_id));return `<div class="booking-person"><span><b>${esc(cl?.class_type||'Class')}</b><small>${esc(cl?.class_date||'')} · ${cl?.class_time?formatTime(cl.class_time.slice(0,5)):''} · ${esc(b.status)}</small></span>${b.status==='booked'?`<button class="btn small danger" onclick="cancelMyBooking('${b.id}')">Cancel</button>`:''}</div>`}).join('')||'<div class="empty">No upcoming bookings.</div>'}</div>`,`My Bookings`,`Your reservations and attendance`)}async function cancelMyBooking(id){if(!confirm('Cancel this booking?'))return;const {error}=await sb.from('bookings').update({status:'cancelled'}).eq('id',id);if(error)return alert(error.message);await loadAll()}
function packages(){const c=myClient();layout(`<div class="grid three">${db.memberships.map(m=>`<div class="card"><h3>${esc(m.name)}</h3><div class="package-price">${money(m.price)}</div><p>${m.sessions===999?'Unlimited':m.sessions+' sessions'} · ${m.validity_days} days</p><button class="btn primary" onclick="requestPackage('${m.id}')">Choose package</button></div>`).join('')}</div><div class="card notice"><b>Online payment setup</b><p>Package selection is active. Card charging will be enabled after a payment provider is connected. Until then, your selection is sent to Core Theory as a pending order.</p></div>`,`Packages`,`Current package: ${esc(c?.package||'None')} · ${c?.sessions??0} sessions remaining`)}async function requestPackage(id){const c=myClient(),m=db.memberships.find(x=>String(x.id)===String(id));const {error}=await sb.from('package_orders').insert({client_id:String(c.id),membership_id:String(m.id),amount:m.price});if(error)return alert(error.message);alert('Package request sent to Core Theory. Payment is pending.')}
function clientaccount(){const c=myClient();layout(`<div class="card compact-card"><h3>${esc(c?.name||profile?.full_name||'Client')}</h3><p>${esc(session.user.email)}</p><p><b>Package:</b> ${esc(c?.package||'None')}</p><p><b>Sessions:</b> ${c?.sessions??0}</p><p><b>Expiry:</b> ${esc(c?.expiry||'—')}</p><button class="btn" onclick="setPasswordScreen()">Change password</button> <button class="btn danger" onclick="logout()">Log out</button></div>`,`My Account`,`Core Theory client portal`)}

function payment(){layout(`<div class="card compact-card"><h3>Record client payment</h3><div class="form"><div class="full"><label>Client</label><select id="rpclient">${db.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div><label>Amount</label><input id="rpamount" type="number" step=".01"></div><div><label>Method</label><select id="rppay"><option>Cash</option><option>Card</option><option>Whish</option><option>Transfer</option></select></div><div class="full"><label>Note</label><input id="rpnote" placeholder="Package / private / other"></div><div class="full"><button class="btn primary" onclick="recordPayment()">Record payment</button></div></div></div>`,`Record Payment`,`Payments are stamped with your account and time`)}async function recordPayment(){const {error}=await sb.from('sales').insert({client_id:$("#rpclient").value,total:+$("#rpamount").value,payment_method:$("#rppay").value,items:[{name:$("#rpnote").value||'Payment'}],created_by:session.user.id});if(error)return alert(error.message);await loadAll();alert('Payment recorded.')}
function expenses(){layout(`<div class="card"><div class="toolbar"><button class="btn primary" onclick="expenseModal()">+ Add expense</button></div>${db.expenses.length?`<table><thead><tr><th>Date</th><th>Category</th><th>Description</th>${isOwner()?'<th>Amount</th><th></th>':''}</tr></thead><tbody>${db.expenses.map(e=>`<tr><td>${esc(e.expense_date)}</td><td>${esc(e.category)}</td><td>${esc(e.description||'')}</td>${isOwner()?`<td>${money(e.amount)}</td><td><button class="btn small danger" onclick="removeItem('expenses','${e.id}')">Delete</button></td>`:''}</tr>`).join('')}</tbody></table>`:'<div class="empty">No expenses.</div>'}</div>`,`Expenses`,isOwner()?'Studio costs and audit trail':'Add expenses; studio totals remain private')}
function expenseModal(){modal('Add expense',`<div class="form"><div><label>Date</label><input type="date" id="edate" value="${today()}"></div><div><label>Category</label><select id="ecat"><option>Electricity</option><option>Rent</option><option>Water</option><option>Internet</option><option>Cleaning</option><option>Payroll</option><option>Inventory</option><option>Marketing</option><option>Maintenance</option><option>Other</option></select></div><div class="full"><label>Description</label><input id="edesc"></div><div><label>Amount</label><input type="number" step=".01" id="eamount"></div><div><label>Payment</label><select id="epay"><option>Cash</option><option>Card</option><option>Whish</option><option>Transfer</option></select></div><div class="full"><button class="btn primary" onclick="addExpense()">Save expense</button></div></div>`)}async function addExpense(){const {error}=await sb.from('expenses').insert({expense_date:$("#edate").value,category:$("#ecat").value,description:$("#edesc").value,amount:+$("#eamount").value,payment_method:$("#epay").value,created_by:session.user.id});if(error)return alert(error.message);$("#modal").remove();await loadAll()}
function memberships(){layout(`<div class="card"><div class="toolbar"><button class="btn primary" onclick="membershipModal()">+ Add membership</button></div>${db.memberships.length?db.memberships.map(m=>`<div class="cart-row"><span><b>${esc(m.name)}</b><small>${m.sessions===999?'Unlimited':m.sessions+' sessions'} · ${m.validity_days} days · ${esc(m.studio_scope||'Both')}</small></span><span class="row"><b>${money(m.price)}</b><button class="btn small" onclick="editMembership('${m.id}')">Edit</button><button class="btn small danger" onclick="removeItem('memberships','${m.id}')">Delete</button></span></div>`).join(''):'<div class="empty">No memberships yet.</div>'}</div>`,`Memberships`,`Packages available to clients`)}
function membershipModal(m=null){const editing=!!m;modal(editing?'Edit membership':'Add membership',`<div class="form"><div><label>Name</label><input id="mname" value="${esc(m?.name||'')}"></div><div><label>Sessions</label><input type="number" id="msessions" value="${m?.sessions??''}"></div><div><label>Price</label><input type="number" step=".01" id="mprice" value="${m?.price??''}"></div><div><label>Validity days</label><input type="number" id="mdays" value="${m?.validity_days??30}"></div><div class="full"><label>Valid for</label><select id="mscope"><option ${(!m||m.studio_scope==='Both'||!m.studio_scope)?'selected':''}>Both</option><option ${m?.studio_scope==='Pilates'?'selected':''}>Pilates</option><option ${m?.studio_scope==='Megacore'?'selected':''}>Megacore</option></select></div><div class="full"><button class="btn primary" onclick="saveMembership('${m?.id||''}')">${editing?'Save changes':'Save membership'}</button></div></div>`)}
function editMembership(id){const m=db.memberships.find(x=>String(x.id)===String(id));if(m)membershipModal(m)}
async function saveMembership(id=''){const payload={name:$("#mname").value.trim(),sessions:+$("#msessions").value,price:+$("#mprice").value,validity_days:+$("#mdays").value,studio_scope:$("#mscope").value};if(!payload.name)return alert('Enter a membership name.');const q=id?sb.from('memberships').update(payload).eq('id',id):sb.from('memberships').insert(payload);const {error}=await q;if(error)return alert(error.message);$("#modal").remove();await loadAll()}
function pos(){const items=[...db.memberships.map(x=>({...x,kind:'membership'})),...db.products.map(x=>({...x,kind:'product'}))];layout(`<div class="pos"><div class="card"><h3>Products & packages</h3><div class="product-grid">${items.map(x=>`<div class="product" onclick="addCart('${x.kind}','${x.id}')"><b>${esc(x.name)}</b><small>${x.kind==='product'?x.stock+' in stock':x.sessions+' sessions'}</small><div>${money(x.price)}</div></div>`).join('')}</div></div><div class="card"><h3>Current sale</h3>${cart.map((x,i)=>`<div class="cart-row"><span>${esc(x.name)}</span><span>${money(x.price)} <button class="btn small" onclick="cart.splice(${i},1);pos()">×</button></span></div>`).join('')||'<div class="empty">Add an item.</div>'}<label>Client</label><select id="saleClient"><option value="">Walk-in</option>${db.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><label>Payment</label><select id="payment"><option>Cash</option><option>Card</option><option>Whish</option><option>Transfer</option></select><h2>${money(cart.reduce((a,x)=>a+Number(x.price),0))}</h2><button class="btn primary full" onclick="checkout()">Complete sale</button></div></div>`,`POS / Sales`,`Sell packages and retail`)}function addCart(kind,id){const src=kind==='product'?db.products:db.memberships,x=src.find(a=>String(a.id)===String(id));cart.push({...x,kind});pos()}async function checkout(){if(!cart.length)return;const cid=$("#saleClient").value||null,total=cart.reduce((a,x)=>a+Number(x.price),0);for(const x of cart)if(x.kind==='membership'&&cid)await applyMembership(cid,x);const {error}=await sb.from('sales').insert({client_id:cid,total,payment_method:$("#payment").value,items:cart,created_by:session.user.id});if(error)return alert(error.message);cart=[];await loadAll();alert('Sale recorded.')}
async function applyMembership(cid,m){const d=new Date();d.setDate(d.getDate()+Number(m.validity_days));return sb.from('clients').update({package:m.name,sessions:m.sessions,expiry:dateISO(d)}).eq('id',cid)}function sellMembership(cid){modal('Add package',`<select id="smid">${db.memberships.map(m=>`<option value="${m.id}">${esc(m.name)} — ${money(m.price)}</option>`).join('')}</select><button class="btn primary full" onclick="confirmMembership('${cid}')">Apply package</button>`)}async function confirmMembership(cid){const m=db.memberships.find(x=>String(x.id)===$("#smid").value);await applyMembership(cid,m);$("#modal").remove();await loadAll()}
function inventory(){layout(`<div class="card"><div class="toolbar"><button class="btn primary" onclick="productModal()">+ Add product</button></div><table><thead><tr><th>Product</th><th>Cost</th><th>Sell</th><th>Stock</th></tr></thead><tbody>${db.products.map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td>${p.stock}</td></tr>`).join('')}</tbody></table></div>`,`Inventory`,`Retail stock`)}function productModal(){modal('Add product',`<div class="form"><div><label>Name</label><input id="pname"></div><div><label>Category</label><input id="pcat" value="Retail"></div><div><label>Cost</label><input id="pcost" type="number" step=".01"></div><div><label>Sell</label><input id="pprice" type="number" step=".01"></div><div><label>Stock</label><input id="pstock" type="number" value="0"></div><div><label>Low stock</label><input id="pmin" type="number" value="5"></div><div class="full"><button class="btn primary" onclick="addProduct()">Save</button></div></div>`)}async function addProduct(){const {error}=await sb.from('products').insert({name:$("#pname").value,category:$("#pcat").value,cost:+$("#pcost").value,price:+$("#pprice").value,stock:+$("#pstock").value,minimum_stock:+$("#pmin").value});if(error)return alert(error.message);$("#modal").remove();await loadAll()}
function finance(){const rev=db.sales.reduce((a,s)=>a+Number(s.total||0),0),exp=db.expenses.reduce((a,e)=>a+Number(e.amount||0),0);layout(`<div class="grid three"><div class="card kpi"><div class="label">Revenue</div><div class="value">${money(rev)}</div></div><div class="card kpi"><div class="label">Expenses</div><div class="value">${money(exp)}</div></div><div class="card kpi"><div class="label">Profit</div><div class="value">${money(rev-exp)}</div></div></div><div class="spacer"></div><div class="card"><h3>Pending package orders</h3>${db.package_orders.filter(o=>o.status==='pending').map(o=>`<div class="cart-row"><span>${esc(db.clients.find(c=>String(c.id)===String(o.client_id))?.name||'Client')} · ${money(o.amount)}</span><span>Pending</span></div>`).join('')||'<div class="empty">None.</div>'}</div>`,`Finance`,`Owner-only studio financials`)}
function team(){layout(`<div class="card"><div class="toolbar"><button class="btn primary" onclick="inviteInstructorModal()">+ Invite Instructor</button><button class="btn" onclick="teamModal()">+ Add non-login team member</button></div><div class="warning" style="margin-bottom:14px">Instructor logins can only be created by the Owner from this page. Clients who sign up themselves always receive Client access.</div><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Role</th><th>Rate / commission</th><th>Login</th><th></th></tr></thead><tbody>${db.team.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${esc(t.email||'—')}</td><td>${esc(t.phone||'')}</td><td>${esc(t.role||'')}</td><td>${esc(t.rate||'')}</td><td><span class="badge ${t.invite_status==='active'?'good':''}">${esc(t.invite_status||'No login')}</span></td><td>${t.email?`<button class="btn small" onclick="resendInstructorInvite('${t.id}')">Resend invite</button> ${t.auth_user_id?`<button class="btn small danger" onclick="toggleInstructorAccess('${t.id}',${t.invite_status==='disabled'?'true':'false'})">${t.invite_status==='disabled'?'Reactivate':'Deactivate login'}</button>`:''}`:''}</td></tr>`).join('')}</tbody></table></div>`,`Team`,`Invite instructors and privately manage staff access and pay information`)}
function inviteInstructorModal(){modal('Invite Instructor',`<div class="form"><div><label>Full name</label><input id="iname" required></div><div><label>Email</label><input id="iemail" type="email" required></div><div><label>Phone number</label><input id="iphone" type="tel" required></div><div><label>Rate / commission</label><input id="irate" placeholder="$20/class or 30%"></div><div class="full"><p class="muted">They'll receive an email invitation and create their own password. Their account will automatically be Instructor access.</p><button class="btn primary" onclick="inviteInstructor()">Send invitation</button></div></div>`)}
async function callStaffAdmin(payload){const {data,error}=await sb.functions.invoke('manage-instructors',{body:payload});if(error)throw new Error(error.message);if(data?.error)throw new Error(data.error);return data}
async function inviteInstructor(){const name=$("#iname").value.trim(),email=$("#iemail").value.trim().toLowerCase(),phone=$("#iphone").value.trim(),rate=$("#irate").value.trim();if(!name||!email||!phone)return alert('Name, email and phone are required.');const btn=document.querySelector('#modal .btn.primary');btn.disabled=true;btn.textContent='Sending…';try{const r=await callStaffAdmin({action:'invite',name,email,phone,redirectTo:location.origin});const {error}=await sb.from('team').insert({name,email,phone,role:'Instructor',rate,auth_user_id:r.user_id,invite_status:'pending'});if(error)throw error;$("#modal").remove();await loadAll();alert('Instructor invitation sent.')}catch(e){alert(e.message)}finally{if(btn){btn.disabled=false;btn.textContent='Send invitation'}}}
async function resendInstructorInvite(id){const t=db.team.find(x=>String(x.id)===String(id));if(!t?.email)return;try{await callStaffAdmin({action:'invite',name:t.name,email:t.email,phone:t.phone,redirectTo:location.origin,resend:true});await sb.from('team').update({invite_status:'pending'}).eq('id',id);await loadAll();alert('Invitation sent.')}catch(e){alert(e.message)}}
async function toggleInstructorAccess(id,enable){const t=db.team.find(x=>String(x.id)===String(id));if(!t?.auth_user_id)return alert('No login is linked to this team member.');if(!confirm(enable?'Reactivate this instructor login?':'Deactivate this instructor login?'))return;try{await callStaffAdmin({action:enable?'activate':'deactivate',user_id:t.auth_user_id});await sb.from('team').update({invite_status:enable?'active':'disabled'}).eq('id',id);await loadAll()}catch(e){alert(e.message)}}
function teamModal(){modal('Add team member',`<div class="form"><div><label>Name</label><input id="tname"></div><div><label>Role</label><input id="trole" value="Staff"></div><div><label>Phone</label><input id="tphone"></div><div><label>Rate / commission</label><input id="trate"></div><div class="full"><button class="btn primary" onclick="addTeam()">Save</button></div></div>`)}async function addTeam(){const {error}=await sb.from('team').insert({name:$("#tname").value,role:$("#trole").value,phone:$("#tphone").value,rate:$("#trate").value,invite_status:'none'});if(error)return alert(error.message);$("#modal").remove();await loadAll()}
function operations(){const ss=db.studio_settings[0]||{};const todayClasses=db.classes.filter(c=>c.class_date===today());const low=db.clients.filter(c=>Number(c.sessions||0)<=1);layout(`<div class="grid two"><div class="card"><h3>Booking rules</h3><div class="form"><div><label>Free cancellation (hours before)</label><input id="cancelHours" type="number" value="${ss.cancellation_hours??12}"></div><div><label>Booking closes (hours before)</label><input id="closeHours" type="number" value="${ss.booking_close_hours??1}"></div><div><label>Book up to (days ahead)</label><input id="aheadDays" type="number" value="${ss.booking_ahead_days??30}"></div><div><label>Late cancel deducts session</label><select id="lateDeduct"><option value="true" ${ss.late_cancel_deduct!==false?'selected':''}>Yes</option><option value="false" ${ss.late_cancel_deduct===false?'selected':''}>No</option></select></div><div class="full"><button class="btn primary" onclick="saveStudioRules()">Save rules</button></div></div></div><div class="card"><h3>Announcements</h3><div class="toolbar"><button class="btn primary" onclick="announcementModal()">+ Announcement</button></div>${db.announcements.map(a=>`<div class="cart-row"><span><b>${esc(a.title)}</b><small>${esc(a.message)}</small></span><button class="btn small danger" onclick="removeItem('announcements','${a.id}')">Delete</button></div>`).join('')||'<div class="empty">No announcements.</div>'}</div><div class="card"><h3>Promo codes</h3><div class="toolbar"><button class="btn primary" onclick="promoModal()">+ Promo code</button></div>${db.promo_codes.map(p=>`<div class="cart-row"><span><b>${esc(p.code)}</b><small>${p.discount_percent}% off</small></span><span>${p.active?'Active':'Off'}</span></div>`).join('')||'<div class="empty">No promo codes.</div>'}</div><div class="card"><h3>Studio alerts</h3><div class="cart-row"><span>Clients with ≤1 session</span><b>${low.length}</b></div><div class="cart-row"><span>Classes today</span><b>${todayClasses.length}</b></div><div class="cart-row"><span>Waitlisted bookings</span><b>${db.bookings.filter(b=>b.status==='waitlist').length}</b></div></div><div class="card"><h3>Data & reports</h3><p class="muted">Export your current studio data for reporting or backup.</p><button class="btn" onclick="exportData()">Export backup JSON</button> <button class="btn" onclick="exportClientsCSV()">Export clients CSV</button></div><div class="card"><h3>Audit log</h3>${db.audit_log.slice(-20).reverse().map(a=>`<div class="cart-row"><span><b>${esc(a.action)}</b><small>${esc(a.details||'')} · ${new Date(a.created_at).toLocaleString()}</small></span></div>`).join('')||'<div class="empty">Activity will appear here.</div>'}</div></div>`,`Operations`,`Rules, waitlists, promos, announcements, exports and audit trail`) }
async function saveStudioRules(){const row={id:1,cancellation_hours:+$('#cancelHours').value,booking_close_hours:+$('#closeHours').value,booking_ahead_days:+$('#aheadDays').value,late_cancel_deduct:$('#lateDeduct').value==='true'};const {error}=await sb.from('studio_settings').upsert(row);if(error)return alert(error.message);await loadAll();alert('Booking rules saved.')}function announcementModal(){modal('New announcement',`<label>Title</label><input id="annTitle"><label>Message</label><textarea id="annMsg"></textarea><button class="btn primary full" onclick="addAnnouncement()">Publish</button>`)}async function addAnnouncement(){const {error}=await sb.from('announcements').insert({title:$('#annTitle').value,message:$('#annMsg').value,created_by:session.user.id});if(error)return alert(error.message);$('#modal').remove();await loadAll()}function promoModal(){modal('New promo code',`<label>Code</label><input id="promoCode"><label>Discount %</label><input id="promoPct" type="number" min="0" max="100"><button class="btn primary full" onclick="addPromo()">Save</button>`)}async function addPromo(){const {error}=await sb.from('promo_codes').insert({code:$('#promoCode').value.trim().toUpperCase(),discount_percent:+$('#promoPct').value,active:true});if(error)return alert(error.message);$('#modal').remove();await loadAll()}function exportData(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='core-theory-backup-'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}function exportClientsCSV(){const rows=[['Name','Email','Phone','Package','Sessions','Expiry'],...db.clients.map(c=>[c.name,c.email,c.phone,c.package,c.sessions,c.expiry])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='core-theory-clients-'+today()+'.csv';a.click()}
function customSectionPage(id){const sec=db.custom_sections.find(x=>String(x.id)===String(id));if(!sec)return page='dashboard',render();const entries=db.custom_entries.filter(x=>String(x.section_id)===String(id));layout(`<div class="card"><div class="toolbar"><button class="btn primary" onclick="customEntryModal('${id}')">+ Add item</button></div>${entries.map(e=>`<div class="cart-row"><span><b>${esc(e.title)}</b><small>${esc(e.notes||'')}</small></span><button class="btn small danger" onclick="removeItem('custom_entries','${e.id}')">Delete</button></div>`).join('')||'<div class="empty">No items yet.</div>'}</div>`,sec.name,'Custom Core Theory section')}function customEntryModal(id){modal('Add item',`<label>Title</label><input id="ceTitle"><label>Notes / details</label><textarea id="ceNotes"></textarea><button class="btn primary full" onclick="addCustomEntry('${id}')">Save</button>`)}async function addCustomEntry(id){const {error}=await sb.from('custom_entries').insert({section_id:id,title:$('#ceTitle').value,notes:$('#ceNotes').value,created_by:session.user.id});if(error)return alert(error.message);$('#modal').remove();await loadAll()}function customSectionModal(){modal('Add menu section',`<label>Section name</label><input id="csName" placeholder="Cleaning Checklist"><label>Icon</label><input id="csIcon" value="•" maxlength="4"><label>Type</label><select id="csType"><option>List</option><option>Notes</option><option>Checklist</option><option>Table</option></select><button class="btn primary full" onclick="addCustomSection()">Add to menu</button>`)}async function addCustomSection(){const {error}=await sb.from('custom_sections').insert({name:$('#csName').value,icon:$('#csIcon').value||'•',section_type:$('#csType').value.toLowerCase(),visible_owner:true,sort_order:100});if(error)return alert(error.message);$('#modal').remove();await loadAll()}
function settings(){const n=db.notification_settings[0]||{};layout(`<div class="grid two"><div class="card"><h3>Class level colors</h3>${db.class_levels.map(l=>`<div class="level-setting"><span>${esc(l.name)}</span><input type="color" value="${esc(l.color)}" onchange="changeLevelColor('${l.id}',this.value)"></div>`).join('')}</div><div class="card"><h3>Booking notifications</h3><p class="muted">Core Theory automatically queues a confirmation when a client books and a reminder for the night before.</p><div class="form"><div><label>Night-before reminder time</label><input id="nTime" type="time" value="${esc((n.reminder_time||'20:00').slice(0,5))}"></div><div><label>Time zone</label><input id="nZone" value="${esc(n.timezone||'Asia/Beirut')}"></div><div><label><input id="nEmailOn" type="checkbox" ${n.email_enabled!==false?'checked':''}> Email reminders</label></div><div><label><input id="nWaOn" type="checkbox" ${n.whatsapp_enabled?'checked':''}> WhatsApp reminders</label></div><div><label>Sender name</label><input id="nSender" value="${esc(n.sender_name||'Core Theory')}"></div><div><label>Sender email</label><input id="nEmail" type="email" value="${esc(n.sender_email||'')}" placeholder="bookings@yourdomain.com"></div><div class="full"><label>WhatsApp Business number</label><input id="nPhone" value="${esc(n.whatsapp_number||'')}" placeholder="+961..."></div><div class="full"><button class="btn primary" onclick="saveNotificationSettings()">Save notification settings</button></div></div><p class="warning">Email/WhatsApp delivery becomes live after a provider is connected. Until then, confirmations and reminders are safely queued with their scheduled send times.</p></div><div class="card"><h3>Menu & Custom Sections</h3><p class="muted">Create your own Owner menu pages for things like cleaning, equipment, suppliers or tasks.</p><button class="btn primary" onclick="customSectionModal()">+ Add Section</button>${db.custom_sections.map(x=>`<div class="cart-row"><span>${esc(x.icon||'•')} <b>${esc(x.name)}</b><small>${esc(x.section_type||'list')}</small></span><button class="btn small danger" onclick="removeItem('custom_sections','${x.id}')">Delete</button></div>`).join('')}</div><div class="card"><h3>App & account</h3><p class="muted">Core Theory is PWA-ready and can be added to a phone home screen from the browser.</p><button class="btn" onclick="setPasswordScreen()">Change password</button></div><div class="card"><h3>Notification queue</h3>${db.notification_queue.slice(0,10).map(q=>`<div class="cart-row"><span><b>${esc(q.kind)}</b><small>${esc(q.channel)} · ${new Date(q.scheduled_for).toLocaleString()}</small></span><span class="badge">${esc(q.status)}</span></div>`).join('')||'<div class="empty">No notifications queued yet.</div>'}</div></div>`,`Settings`,`Customize classes, reminders and account`) }
async function saveNotificationSettings(){const row={id:1,reminder_time:$("#nTime").value||'20:00',timezone:$("#nZone").value||'Asia/Beirut',email_enabled:$("#nEmailOn").checked,whatsapp_enabled:$("#nWaOn").checked,sender_name:$("#nSender").value.trim()||'Core Theory',sender_email:$("#nEmail").value.trim(),whatsapp_number:$("#nPhone").value.trim(),updated_at:new Date().toISOString()};const {error}=await sb.from('notification_settings').upsert(row);if(error)return alert(error.message);await loadAll();alert('Notification settings saved.')}async function changeLevelColor(id,color){const {error}=await sb.from('class_levels').update({color}).eq('id',id);if(error)return alert(error.message);await loadAll()}
function account(){layout(`<div class="card compact-card"><h3>${esc(profile?.full_name||'Instructor')}</h3><p>${esc(session.user.email)}</p><p class="muted">You can see only your assigned classes and the booked client names needed for attendance. Client lists, expenses, finance and other instructors’ schedules remain private.</p><button class="btn" onclick="setPasswordScreen()">Set / change password</button></div>`,`Account`,`Instructor access`)}
function clientModal(){modal('Add client',`<div class="form"><div><label>Name</label><input id="cname"></div><div><label>Phone</label><input id="cphone"></div><div><label>Email</label><input id="cemail"></div><div class="full"><button class="btn primary" onclick="addClient()">Save</button></div></div>`)}async function addClient(){const {error}=await sb.from('clients').insert({name:$("#cname").value,phone:$("#cphone").value,email:$("#cemail").value,sessions:0});if(error)return alert(error.message);$("#modal").remove();await loadAll()}
function modal(title,body){$("#modal")?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-wrap" id="modal"><div class="modal"><div class="row modal-head"><h2>${title}</h2><button class="btn" onclick="$('#modal').remove()">×</button></div>${body}</div></div>`)}async function removeItem(table,id){if(!isOwner())return;if(!confirm('Delete this item?'))return;const {error}=await sb.from(table).delete().eq('id',id);if(error)return alert(error.message);await loadAll()}
async function init(){const recovery=location.hash.includes('type=recovery')||location.hash.includes('type=invite')||location.search.includes('type=recovery')||location.search.includes('type=invite');const {data}=await sb.auth.getSession();session=data.session;sb.auth.onAuthStateChange(async(event,s)=>{session=s;if(event==='PASSWORD_RECOVERY')return setPasswordScreen();if(!s)return authScreen()});if(!session)return authScreen();if(recovery)return setPasswordScreen();await loadAll();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{})}init();
